const RunwayEngine=(()=>{const initPreloader=()=>new Promise(resolve=>{const preloader=document.getElementById("preloader");if(!preloader){resolve();return}const logo=preloader.querySelector(".preloader-logo");const thread=preloader.querySelector(".preloader-thread");const curtainTop=preloader.querySelector(".preloader-curtain--top");const curtainBottom=preloader.querySelector(".preloader-curtain--bottom");document.body.classList.add("is-loading");const tl=gsap.timeline({onComplete:()=>{preloader.style.display="none";document.body.classList.remove("is-loading");resolve()}});tl.to(logo,{opacity:1,duration:1.2,ease:"power2.out"}).to(thread,{width:"120px",duration:.8,ease:"power4.inOut"},"-=0.3").to({},{duration:.5}).to([logo,thread],{opacity:0,duration:.4,ease:"power2.in"}).to(curtainTop,{yPercent:-100,duration:1.2,ease:"power4.inOut"},"-=0.1").to(curtainBottom,{yPercent:100,duration:1.2,ease:"power4.inOut"},"<")});const init=async()=>{await initPreloader();const lenis=new Lenis({duration:1.2,easing:t=>Math.min(1,1.001-Math.pow(2,-10*t)),direction:"vertical",gestureDirection:"vertical",smooth:true,mouseMultiplier:1,smoothTouch:false,touchMultiplier:2,infinite:false});gsap.registerPlugin(ScrollTrigger);lenis.on("scroll",ScrollTrigger.update);gsap.ticker.add(time=>{lenis.raf(time*1e3)});gsap.ticker.lagSmoothing(0);initCustomCursor();initCollectionsReveal();initHorizontalScroll();initRunwayItems();initEmailProtection()};const initCollectionsReveal=()=>{const collectionsSection=document.querySelector(".collections");if(!collectionsSection)return;const headerMaskTexts=collectionsSection.querySelectorAll(".collections-header .mask-text");gsap.set(headerMaskTexts,{yPercent:100});ScrollTrigger.create({trigger:collectionsSection,start:"top 75%",animation:gsap.timeline().to(headerMaskTexts,{yPercent:0,duration:1.2,stagger:.15,ease:"power4.out"})})};const initHorizontalScroll=()=>{const wrapper=document.querySelector(".horizontal-scroll-wrapper");const track=document.querySelector(".horizontal-scroll-track");if(!wrapper||!track)return;const slides=track.querySelectorAll(".runway-slide");const counterCurrent=document.querySelector(".slide-counter-current");const totalSlides=slides.length;const getScrollAmount=()=>-(track.scrollWidth-wrapper.clientWidth);gsap.to(track,{x:getScrollAmount,ease:"none",scrollTrigger:{trigger:wrapper,start:"top 15%",end:()=>`+=${track.scrollWidth-wrapper.clientWidth}`,scrub:1,pin:true,anticipatePin:1,invalidateOnRefresh:true,onUpdate:self=>{if(counterCurrent){const index=Math.min(Math.floor(self.progress*totalSlides)+1,totalSlides);const formatted=String(index).padStart(2,"0");if(counterCurrent.textContent!==formatted){counterCurrent.textContent=formatted}}}}})};const initRunwayItems=()=>{const simpleItems=document.querySelectorAll(".runway-item");simpleItems.forEach(item=>{ScrollTrigger.create({trigger:item,start:"top 85%",onEnter:()=>item.classList.add("is-visible"),once:true})})};const initEmailProtection=()=>{const emailBtns=document.querySelectorAll(".secure-email-btn");emailBtns.forEach(btn=>{btn.addEventListener("click",e=>{e.preventDefault();const user="contacto";const domain="auracarmona.com";window.location.href=`mailto:${user}@${domain}`})})};const initCustomCursor=()=>{const cursor=document.querySelector(".custom-cursor");const cursorText=document.querySelector(".custom-cursor-text");if(!cursor)return;gsap.set(cursor,{xPercent:-12.5,yPercent:-87.5});const xTo=gsap.quickTo(cursor,"x",{duration:.4,ease:"power3.out"});const yTo=gsap.quickTo(cursor,"y",{duration:.4,ease:"power3.out"});window.addEventListener("mousemove",e=>{xTo(e.clientX);yTo(e.clientY)});const interactables=document.querySelectorAll("a, button, .model-img");interactables.forEach(el=>{el.addEventListener("mouseenter",()=>{cursor.classList.add("is-active");if(el.classList.contains("model-img")){cursorText.textContent="Ver"}else{cursorText.textContent="Explorar"}});el.addEventListener("mouseleave",()=>{cursor.classList.remove("is-active")})})};const setCopyrightYear=()=>{const yearElement=document.getElementById("current-year");if(yearElement){yearElement.textContent=(new Date).getFullYear()}};const boot=()=>{init();setCopyrightYear()};return{init:boot}})();document.addEventListener("DOMContentLoaded",()=>{RunwayEngine.init()});